  .domain{display:grid;gap:var(--space-4)}.tabs{display:flex;flex-wrap:wrap;gap:var(--space-2)}button,select{min-height:44px;padding:0 var(--space-3);border:1px solid var(--color-border);border-radius:var(--radius-control);background:var(--color-surface);color:var(--color-text-primary)}button.active,button.primary{border-color:var(--color-info-border);background:var(--color-info-subtle)}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:var(--space-3)}article,.settings section{display:grid;gap:var(--space-3);padding:var(--space-4);border:1px solid var(--color-border);border-radius:var(--radius-card);background:var(--color-surface)}h2,h3,p{margin:0}small,p,dt{color:var(--color-text-muted)}article>div:first-child{display:grid;gap:4px}.checks{display:grid;gap:var(--space-3)}.checks article{grid-template-columns:auto 1fr;align-items:start}.settings{grid-template-columns:repeat(2,minmax(0,1fr))}.settings label{display:flex;align-items:center;justify-content:space-between;gap:var(--space-3);min-height:44px}dl{display:grid;gap:var(--space-3);margin:0}dl div{display:flex;justify-content:space-between;gap:var(--space-3)}dd{margin:0;text-align:right}@media(max-width:700px){.settings{grid-template-columns:1fr}.settings label{align-items:flex-start;flex-direction:column}select{width:100%}}
</style>
